INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > SQL > SELECT-Aufbau
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die FROM-Klausel in einem SQL-SELECT-Statement zwingend erforderlich?', 2, '[{"text": "Ja", "correct": true, "because": "FROM gibt die Tabelle an, aus der Daten abgerufen werden"}, {"text": "Nein", "correct": false, "because": "Ohne FROM kein Datenbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die WHERE-Klausel in einem SELECT-Statement mehrere Bedingungen kombinieren?', 2, '[{"text": "Ja", "correct": true, "because": "WHERE unterstützt AND, OR etc."}, {"text": "Nein", "correct": false, "because": "Mehrere Bedingungen sind möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird mit JOIN in einem SELECT-Statement immer eine Verbindung zwischen zwei Tabellen hergestellt?', 2, '[{"text": "Ja", "correct": true, "because": "JOIN verknüpft Tabellen basierend auf Bedingungen"}, {"text": "Nein", "correct": false, "because": "Zweck von JOIN"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die GROUP BY-Klausel in einem SELECT-Statement immer mit Aggregatfunktionen wie SUM verwendet werden?', 2, '[{"text": "Nein", "correct": true, "because": "GROUP BY kann ohne Aggregatfunktionen genutzt werden, aber oft mit"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die LIMIT-Klausel die Anzahl der zurückgegebenen Zeilen in einem SELECT-Statement beschränken?', 2, '[{"text": "Ja", "correct": true, "because": "LIMIT begrenzt die Ausgabe"}, {"text": "Nein", "correct": false, "because": "Hauptfunktion von LIMIT"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Klausel in einem SELECT-Statement gibt die Tabelle an, aus der Daten abgerufen werden?', 2, '[{"text": "FROM", "correct": true, "because": "FROM definiert die Datenquelle"}, {"text": "WHERE", "correct": false, "because": "Filtert Daten"}, {"text": "JOIN", "correct": false, "because": "Verknüpft Tabellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klausel filtert die Ergebnisse eines SELECT-Statements basierend auf Bedingungen?', 3, '[{"text": "WHERE", "correct": true, "because": "WHERE wendet Bedingungen an"}, {"text": "GROUP BY", "correct": false, "because": "Gruppiert Daten"}, {"text": "HAVING", "correct": false, "because": "Filtert Gruppen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klausel verbindet zwei Tabellen in einem SELECT-Statement?', 2, '[{"text": "JOIN", "correct": true, "because": "JOIN verknüpft Tabellen"}, {"text": "FROM", "correct": false, "because": "Gibt nur Quelle an"}, {"text": "LIMIT", "correct": false, "because": "Begrenzt Ergebnisse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klausel sortiert die Ergebnisse eines SELECT-Statements?', 2, '[{"text": "ORDER BY", "correct": true, "because": "ORDER BY sortiert Ausgabe"}, {"text": "GROUP BY", "correct": false, "because": "Gruppiert Daten"}, {"text": "HAVING", "correct": false, "because": "Filtert Gruppen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klausel begrenzt die Anzahl der Zeilen in einem SELECT-Statement?', 2, '[{"text": "LIMIT", "correct": true, "because": "LIMIT schränkt Ergebnisse ein"}, {"text": "WHERE", "correct": false, "because": "Filtert Bedingungen"}, {"text": "JOIN", "correct": false, "because": "Verknüpft Tabellen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Klauseln gehören zum Aufbau eines SELECT-Statements?', 4, '[{"text": "FROM", "correct": true, "because": "Datenquelle"}, {"text": "WHERE", "correct": true, "because": "Filterung"}, {"text": "JOIN", "correct": true, "because": "Tabellenverknüpfung"}, {"text": "INSERT", "correct": false, "because": "DML-Befehl, kein SELECT"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen kann die WHERE-Klausel in einem SELECT-Statement erfüllen?', 3, '[{"text": "Daten filtern", "correct": true, "because": "Bedingungen anwenden"}, {"text": "Vergleichsoperatoren nutzen", "correct": true, "because": "=, <, > etc."}, {"text": "Logische Operatoren kombinieren", "correct": true, "because": "AND, OR"}, {"text": "Daten sortieren", "correct": false, "because": "ORDER BY"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche JOIN-Typen können in einem SELECT-Statement verwendet werden?', 4, '[{"text": "INNER JOIN", "correct": true, "because": "Nur übereinstimmende Daten"}, {"text": "LEFT JOIN", "correct": true, "because": "Alle Daten der linken Tabelle"}, {"text": "RIGHT JOIN", "correct": true, "because": "Alle Daten der rechten Tabelle"}, {"text": "WHERE JOIN", "correct": false, "because": "Kein JOIN-Typ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klauseln können die Ergebnisse eines SELECT-Statements weiter verfeinern?', 3, '[{"text": "GROUP BY", "correct": true, "because": "Gruppiert Daten"}, {"text": "HAVING", "correct": true, "because": "Filtert Gruppen"}, {"text": "ORDER BY", "correct": true, "because": "Sortiert Ergebnisse"}, {"text": "FROM", "correct": false, "because": "Nur Datenquelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat die LIMIT-Klausel in einem SELECT-Statement?', 3, '[{"text": "Begrenzt die Anzahl der Zeilen", "correct": true, "because": "Hauptfunktion"}, {"text": "Kann mit OFFSET kombiniert werden", "correct": true, "because": "Verschiebt Startpunkt"}, {"text": "Beschränkt die Ausgabe", "correct": true, "because": "Reduziert Ergebnisse"}, {"text": "Gruppiert Daten", "correct": false, "because": "GROUP BY"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) FROM ist in jedem SELECT-Statement erforderlich. b) WHERE sortiert die Ergebnisse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "FROM ja, WHERE filtert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) JOIN verknüpft Tabellen in einem SELECT-Statement. b) GROUP BY filtert einzelne Zeilen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "JOIN ja, GROUP BY gruppiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) HAVING filtert Gruppen nach einer Aggregation. b) ORDER BY ist zwingend erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "HAVING ja, ORDER BY optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) LIMIT kann die Anzahl der Ergebnisse beschränken. b) WHERE gruppiert Daten nach Kategorien.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "LIMIT ja, WHERE filtert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) GROUP BY kann mit HAVING kombiniert werden. b) JOIN ist nur für eine Tabelle möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "GROUP BY/HAVING ja, JOIN mehrere Tabellen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

